  'detail.buy.gateway': { ko: '구매 주소', en: 'Purchase address' },
  'detail.buy.gateway_moved': { ko: '공개 기록에 적힌 주소({old})는 판매 노드가 더 이상 쓰지 않습니다 — 위 주소는 이 노드가 지금 확인한 위치입니다.', en: 'The address written into the public record ({old}) is not where this seller answers any more — the one above is where this node currently sees it.' },
  'detail.buy.gateway_seen': { ko: '이 판매 노드가 마지막으로 응답한 시각: {when}.', en: 'This seller last answered {when}.' },
  'detail.buy.agent_title': { ko: 'AI 에이전트로 사기', en: 'Buy with an AI agent' },
  'detail.buy.agent_text': { ko: '사람 대신 AI 에이전트가 살 수도 있습니다. 에이전트는 모델이 모르는 질문을 만나면 이 지식을 찾아 자동 결제하고, 검증된 파일만 받아 바로 모델에 넣습니다. 설정 방법은 노드 운영자·개발자 문서(CLI·API)를 참고하세요.', en: 'An AI agent can buy on your behalf: when the model cannot answer, the agent finds this knowledge, pays automatically, accepts only verified files and loads them at once. See the operator & developer docs (CLI & API).' },
  'detail.buy.agent_link': { ko: '노드 운영자·개발자 문서 ›', en: 'Operator & developer docs ›' },
  'detail.buy.dev_summary': { ko: '노드 운영자·개발자용: 명령줄·API로 구매', en: 'For node operators & developers: buy from the command line / API' },
  'detail.buy.dev_note': { ko: '자동 결제의 실제 프로토콜입니다. 첫 요청에 가격 안내가 돌아오고, 결제 증빙을 붙여 다시 요청하면 파일 정보(매니페스트)를 받습니다.', en: 'The actual automatic-payment protocol: the first request returns a quote; retry with the payment proof to receive the manifest.' },
