  'detail.buy.curl_4': { ko: '# AI 에이전트: 모르는 답 감지 → 검색 → 자동 결제 → 모델에 넣기', en: '# AI agent: detect unknown answer → search → auto-pay → load' },
  'detail.buy.from_node': { ko: '이 노드에서 구매', en: 'Buy from this node' },
